#include <stdio.h>
#include <ctype.h>
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    char digits[1000]; int idx = 0;
    for (int i = 0; s[i]; i++) if (isdigit(s[i])) digits[idx++] = s[i];
    digits[idx] = '\0';
    if (idx == 0) puts("0");
    else {
        int start = 0;
        while (start < idx - 1 && digits[start] == '0') start++;
        puts(digits + start);
    }
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <cctype>
using namespace std;
int main() {
    string s; if (!getline(cin, s)) return 0;
    string d = "";
    for (char c : s) if (isdigit(c)) d += c;
    if (d.empty()) cout << "0\n";
    else {
        size_t start = d.find_first_not_of('0');
        cout << (start == string::npos ? "0" : d.substr(start)) << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine();
            String d = s.replaceAll("\\D+", "");
            if (d.isEmpty()) System.out.println("0");
            else System.out.println(d.replaceFirst("^0+(?!$)", ""));
        }
    }
}

